      "rationale": "These spans establish the initial information gap, the operation for documenting timing, and the restriction on inferring intent from silence."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C006.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
